url_options.data:
{
  "size": 0,
  "query": {
    "bool": {
      "filter": [
        {
          "range": {
            "@timestamp": {
              "gte": "${__from}",
              "lte": "${__to}"
            }
          }
        },
        {
          "term": {
            "session.player.platform": "Web"
          }
        },
        {
          "wildcard": {
            "session.player.name": "${player}"
          }
        },
        {
          "wildcard": {
            "session.browser.name": "${browser}"
          }
        },
        {
          "wildcard": {
            "session.media.bu": "${bu}"
          }
        },
        {
          "wildcard": {
            "session.media.type": "${type}"
          }
        },
        {
          "wildcard": {
            "session.media.id": "${media_id}"
          }
        },
        {
          "query_string": {
            "query": "session.media.swisstxt:${swisstxt:raw}"
          }
        },
        {
          "terms": {
            "event_name": [
              "ERROR",
              "START"
            ]
          }
        }
      ]
    }
  },
  "aggs": {
    "g": {
      "multi_terms": {
        "terms": [
          {
            "field": "session.browser.name"
          },
          {
            "field": "session.os.name"
          }
        ],
        "size": 500,
        "order": {
          "starts": "desc"
        }
      },
      "aggs": {
        "errors": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                }
              ],
              "must_not": [
                {
                  "terms": {
                    "data.error_type": [
                      "DRM_NOT_SUPPORTED",
                      "CONNECTION_ERROR"
                    ]
                  }
                }
              ]
            }
          }
        },
        "starts": {
          "filter": {
            "term": {
              "event_name": "START"
            }
          }
        },
        "error_rate": {
          "bucket_script": {
            "buckets_path": {
              "err": "errors>_count",
              "sess": "starts>_count"
            },
            "script": "params.sess > 0 ? params.err / params.sess : 0"
          }
        },
        "success_rate": {
          "bucket_script": {
            "buckets_path": {
              "err": "errors>_count",
              "sess": "starts>_count"
            },
            "script": "params.sess > 0 ? 1 - params.err / params.sess : 0"
          }
        },
        "m0": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                },
                {
                  "query_string": {
                    "query": "data.log:MEDIA_ERR_DECODE"
                  }
                }
              ]
            }
          }
        },
        "m1": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                },
                {
                  "query_string": {
                    "query": "data.log:MEDIA_ERR_SRC_NOT_SUPPORTED"
                  }
                }
              ]
            }
          }
        },
        "m2": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                },
                {
                  "query_string": {
                    "query": "data.log:MEDIA_ERR_ENCRYPTED"
                  }
                }
              ]
            }
          }
        },
        "m3": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                },
                {
                  "query_string": {
                    "query": "data.log:MEDIA_ERR_NETWORK"
                  }
                }
              ]
            }
          }
        },
        "m4": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                },
                {
                  "query_string": {
                    "query": "data.log:IL_ERROR OR data.log:httpStatusCode"
                  }
                }
              ]
            }
          }
        }
      }
    }
  }
}

